//! 👯️ Heterogeneous defaults retain each authentic child across separate return and close turns.
use super::*;
pub struct NativePairDefaultCursor<A:NativeDefault,B:NativeDefault>{first_child:NativeDefaultSlot<A>,second_child:NativeDefaultSlot<B>,first:ManuallyDrop<Option<A>>,second:ManuallyDrop<Option<B>>,output:ManuallyDrop<Option<(A,B)>>,retirement:RetainedCloneClose,phase:u8,closing:bool}
impl<A:NativeDefault,B:NativeDefault>NativePairDefaultCursor<A,B>{pub fn new()->Self{Self{first_child:NativeDefaultSlot::new(),second_child:NativeDefaultSlot::new(),first:ManuallyDrop::new(None),second:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,closing:false}}}
impl<A:NativeDefault,B:NativeDefault>NativeDefault for(A,B){type Cursor=NativePairDefaultCursor<A,B>;fn default_cursor()->Self::Cursor{NativePairDefaultCursor::new()}}
impl<A:NativeDefault,B:NativeDefault>NativeDefaultCursor<(A,B)>for NativePairDefaultCursor<A,B>{
 fn demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}match self.phase{0=>if self.first_child.ready(){Ok(fixed(0))}else{self.first_child.demands(body)},1=>if self.first_child.terminal_is_empty(){Ok(fixed(0))}else{self.first_child.close_demands(body)},2=>if self.second_child.ready(){Ok(fixed(0))}else{self.second_child.demands(body)},3=>if self.second_child.terminal_is_empty(){Ok(fixed(0))}else{self.second_child.close_demands(body)},4|5=>Ok(fixed(0)),_=>Err(invalid())}}
 fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{if self.output_ready(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.demands(body){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if let Err(e)=control.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}
  match self.phase{0=>{if !self.first_child.ready(){let turn=self.first_child.advance(control,body,g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:turn.work}}let turn=self.first_child.take(g);let result=turn.result.and_then(|value|{let Some((value,p))=value else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.first=Some(value);self.first_child.begin_close();self.phase=1;Ok(RetainedCloneStep::Progress(p))});return RetainedWorkOutcome{result:result.map_err(Into::into),work:turn.work}},1 if !self.first_child.terminal_is_empty()=>{let turn=self.first_child.close_step(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}},2=>{if !self.second_child.ready(){let turn=self.second_child.advance(control,body,g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:turn.work}}let turn=self.second_child.take(g);let result=turn.result.and_then(|value|{let Some((value,p))=value else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.second=Some(value);self.second_child.begin_close();self.phase=3;Ok(RetainedCloneStep::Progress(p))});return RetainedWorkOutcome{result:result.map_err(Into::into),work:turn.work}},3 if !self.second_child.terminal_is_empty()=>{let turn=self.second_child.close_step(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}},_=>{}}
  let p=receipt(fixed(0));let result=(||{match self.phase{1=>self.phase=2,3=>self.phase=4,4=>{if self.first.is_none()||self.second.is_none(){return Err(invalid().with_retained_progress(p))}*self.output=Some((self.first.take().unwrap(),self.second.take().unwrap()));self.phase=5;},_=>return Err(invalid().with_retained_progress(p))}Ok(if self.output_ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})})();control.receive_retained_work(g,RetainedWorkOutcome{result,work:1})
 }
 fn output_ready(&self)->bool{!self.closing&&self.phase==5&&self.output.is_some()}
 fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<((A,B),RetainedCloneProgress)>>{if !self.output_ready()||!retained_clone_grant_admits(g,fixed(0)){return RetainedWorkOutcome{result:Ok(None),work:0}}RetainedWorkOutcome{result:Ok(Some((self.output.take().unwrap(),receipt(fixed(0))))),work:1}}
 fn begin_close(&mut self){self.closing=true;self.first_child.begin_close();self.second_child.begin_close();}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.first_child.terminal_is_empty(){return self.first_child.close_demands(body)}if !self.second_child.terminal_is_empty(){return self.second_child.close_demands(body)}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.first.is_some(){return self.retirement.next_owner_demands::<A>(true,&None,body)}if self.second.is_some(){return self.retirement.next_owner_demands::<B>(true,&None,body)}self.retirement.next_owner_demands::<(A,B)>(self.output.is_some(),&None,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if !self.first_child.terminal_is_empty(){let turn=self.first_child.close_step(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:turn.work}}if !self.second_child.terminal_is_empty(){let turn=self.second_child.close_step(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:turn.work}}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:turn.work}}let turn=if self.first.is_some(){self.retirement.begin_granted(&mut self.first,g)}else if self.second.is_some(){self.retirement.begin_granted(&mut self.second,g)}else{self.retirement.begin_granted(&mut self.output,g)};RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}
 fn terminal_is_empty(&self)->bool{self.first_child.terminal_is_empty()&&self.second_child.terminal_is_empty()&&self.first.is_none()&&self.second.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<A:NativeDefault,B:NativeDefault>Drop for NativePairDefaultCursor<A,B>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native pair default requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.first);ManuallyDrop::drop(&mut self.second);ManuallyDrop::drop(&mut self.output);}}}}
